double[] samples = {20, 21, 19, 22, 200};
double mean = samples.Average();
double[] ordered = samples.Order().ToArray();
double median = ordered[ordered.Length / 2]; // odd sample count in this lab
int rank95 = (int)Math.Ceiling(0.95 * ordered.Length);
double p95NearestRank = ordered[rank95 - 1];
int overDeadline = samples.Count(x => x > 100);
Console.WriteLine($"n={samples.Length} mean={mean} median={median} p95={p95NearestRank} over100={overDeadline}");
